/* Majlis — narrated video scripts, days 16–30 */
window.MAJLIS_GUIDE_VIDEOS = Object.assign(window.MAJLIS_GUIDE_VIDEOS || {}, {
  16: { minutes: 3, beats: [
    { type: "title", heading: "Rule by the People?", text: "Day sixteen. Democracy is the world's most popular system, which is exactly why its critics deserve a hearing." },
    { type: "idea", icon: "ballot", headline: "Demos plus kratos", sub: "Greek for people plus power: rule by the people.", text: "Demos means people and kratos means power, so democracy is rule by the people. Simple idea, complicated reality.", say: "Day-moss means people and krah-toss means power, so democracy is rule by the people. Simple idea, complicated reality." },
    { type: "idea", icon: "people", headline: "Athens: everyone votes in person", sub: "Adult male citizens voted directly on laws, war and peace.", text: "In ancient Athens, adult male citizens gathered in an assembly and voted directly on laws, war and peace. No representatives." },
    { type: "example", icon: "school", headline: "Picked out of a hat", sub: "Imagine your class rep chosen by lottery instead of an election.", text: "Many officials were chosen by lot. Imagine your class rep picked out of a hat, because Athenians thought elections favoured the rich and famous." },
    { type: "idea", icon: "chain", headline: "Far from equal", sub: "Women, slaves and foreigners were shut out completely.", text: "But women, slaves and foreigners were excluded. Still, the idea that ordinary people could govern themselves was revolutionary." },
    { type: "thinker", name: "Pericles", dates: "c. 495–429 BC", line: "Govern in the interests of the many.", text: "Thucydides records a speech by the Athenian leader Pericles, praising Athens for governing in the interests of the many, not the few.", say: "Thoo-sid-i-deez records a speech by the Athenian leader Pericles, praising Athens for governing in the interests of the many, not the few." },
    { type: "idea", icon: "scale", headline: "Representative democracy", sub: "We elect people to decide; courts, constitutions and a free press limit them.", text: "Today most democracies are representative. Instead of voting on every law, we elect people to decide for us, and constitutions, courts and a free press limit what they can do." },
    { type: "list", headline: "Why democracy?", items: ["Every citizen gets one vote", "Bad leaders removed peacefully", "Draws on many people's knowledge", "Free press helps prevent famine"], text: "So why democracy? It treats citizens as equals, removes bad leaders without violence, and pools many people's knowledge. Amartya Sen argued democracies rarely suffer famines, because a free press and elections force governments to respond." },
    { type: "question", big: "What if most voters don't know much?", text: "Now for the critics, and their first punch lands hard. What if most voters simply don't know much?" },
    { type: "thinker", name: "Plato", dates: "c. 428–348 BC", line: "Ignorant voters fall for flatterers.", text: "Plato thought most voters lack knowledge and are swayed by flattery. That opens the door to demagogues, smooth talkers who tell crowds what they want to hear, and eventually to tyranny." },
    { type: "thinker", name: "Alexis de Tocqueville", dates: "1805–1859", line: "Beware the tyranny of the majority.", text: "In the 1830s, the French writer Alexis de Tocqueville admired American democracy, but he warned of the tyranny of the majority. A majority can oppress minorities just as a king can.", say: "In the 1830s, the French writer Alexis de Tock-vil admired American democracy, but he warned of the tyranny of the majority. A majority can oppress minorities just as a king can." },
    { type: "example", icon: "phone", headline: "The group chat vote", sub: "The same twenty friends outvote the same two, every time.", text: "Picture a group chat where the same twenty people outvote the same two people, every single time. Fair process, maybe. But how does it feel to be one of the two?" },
    { type: "idea", icon: "brain", headline: "Epistocracy?", sub: "Extra voting weight for better-informed voters. Most people find it troubling.", text: "Political scientists show many voters know little about policy and vote by group loyalty. Some philosophers, like Jason Brennan, even propose epistocracy, extra weight for more informed voters, though most people find that troubling.", say: "Political scientists show many voters know little about policy and vote by group loyalty. Some philosophers, like Jason Brennan, even propose e-pis-tock-ra-see, extra weight for more informed voters, though most people find that troubling." },
    { type: "list", headline: "Other traditions", items: ["Islam: shura, or consultation", "Confucian: virtuous, educated officials", "Gulf: consultative councils"], text: "In Islamic thought, shura, meaning consultation, comes from the Quran, and scholars debate how far it supports democracy. Confucians stress virtuous, educated officials, and Gulf monarchies point to consultative councils.", say: "In Islamic thought, shoo-ra, meaning consultation, comes from the Quran, and scholars debate how far it supports democracy. Confucians stress virtuous, educated officials, and Gulf monarchies point to consultative councils." },
    { type: "scale", left: "Equal say", right: "Good decisions", headline: "Value or results?", tilt: 0, text: "Defenders reply that experts can be wrong and self-interested too. Democracy's strength is that power is shared and leaders can be removed." },
    { type: "recap", items: ["Athens: direct democracy, officials by lot", "Equality, peaceful change, pooled knowledge", "Critics: ignorance, demagogues, majority tyranny", "Shura and Confucian merit offer alternatives"], text: "Quick recap. Athens pioneered direct democracy. Defenders point to equality and peaceful change, critics to ignorance and tyranny of the majority, and other traditions offer their own models of accountable rule." },
    { type: "debate", motion: "Should the voting age be lowered to 16?", text: "Now it's your turn. Should the voting age be lowered to sixteen? Think about values and results, then make your case on Majlis." }
  ] },
  17: { minutes: 3, beats: [
    { type: "title", heading: "Rights for All?", text: "Day seventeen. In 1948, nations that disagreed about almost everything agreed on one list of rights for every human. How?" },
    { type: "idea", icon: "shield", headline: "A right creates a duty", sub: "If you have a right to speak, others must not silence you.", text: "First, what is a right? A claim you are entitled to make. If you have a right to free speech, others have a duty not to silence you." },
    { type: "question", big: "Where do rights come from?", text: "Where do rights come from? Governments, God, or human nature? If only from government, government can take them away." },
    { type: "example", icon: "phone", headline: "Can school search your phone?", sub: "Your answer depends on where you think rights come from.", text: "Try it at school. Can a teacher search your phone? Your answer depends on whether privacy is a gift from the rulebook, or something you have anyway." },
    { type: "timeline", events: [{ year: "1215", label: "Magna Carta limits the king" }, { year: "1776", label: "American Declaration" }, { year: "1789", label: "French Declaration of Rights" }, { year: "1948", label: "Universal Declaration adopted" }], text: "The idea grew over centuries: Magna Carta limited royal power in 1215, then came the American Declaration of Independence in 1776 and the French Declaration of the Rights of Man in 1789." },
    { type: "thinker", name: "John Locke", dates: "1632–1704", line: "Everyone has natural rights: life, liberty, property.", text: "John Locke argued that everyone has natural rights to life, liberty and property. Not handed out by kings, simply yours as a human." },
    { type: "quote", quote: "Nonsense upon stilts.", by: "Jeremy Bentham, on natural rights", text: "Jeremy Bentham called natural rights nonsense upon stilts. For him, rights were created by law, not found before it." },
    { type: "versus", left: { name: "Edmund Burke", line: "Inherited rights of a people, not abstractions." }, right: { name: "Karl Marx", line: "Rights talk can protect property over people." }, text: "Edmund Burke preferred a people's inherited rights to abstract universal ones. Karl Marx worried rights talk could protect property more than people." },
    { type: "idea", icon: "globe", headline: "After the Second World War", sub: "The new United Nations set out rights for every human being.", text: "Then came the horrors of the Second World War and the Holocaust. The newly formed United Nations set out to declare rights that would belong to every single human being." },
    { type: "thinker", name: "Eleanor Roosevelt", dates: "1884–1962", line: "Rights for every human, drafted by many cultures.", text: "The drafting committee was chaired by Eleanor Roosevelt. It included the Lebanese philosopher Charles Malik, the Chinese thinker Peng Chun Chang, who drew on Confucian ideas, and the French jurist René Cassin.", say: "The drafting committee was chaired by Eleanor Roosevelt. It included the Lebanese philosopher Charles Malik, the Chinese thinker Peng Chun Chang, who drew on Confucian ideas, and the French jurist Ruh-nay Ka-sahn." },
    { type: "list", headline: "10 December 1948", items: ["48 countries voted in favour", "None voted against", "Eight abstained"], text: "On the tenth of December 1948, the UN General Assembly adopted the Universal Declaration of Human Rights: forty-eight in favour, none against, eight abstentions." },
    { type: "idea", icon: "scroll", headline: "Thirty articles", sub: "All human beings are born free and equal in dignity and rights.", text: "The Declaration has thirty articles. Article one says all human beings are born free and equal in dignity and rights, and others ban torture and slavery and protect freedom of thought, conscience and religion." },
    { type: "idea", icon: "book", headline: "The Cairo Declaration", sub: "1990: rights affirmed within the framework of Islamic law.", text: "In 1990, the Organisation of Islamic Cooperation adopted the Cairo Declaration, affirming many rights within Islamic law. Supporters see a culturally grounded approach; critics say it limits some rights, like freedom of religion." },
    { type: "scale", left: "Privacy", right: "Security", headline: "Two rights in tension", tilt: 0, text: "In debates, ask where your opponent thinks rights come from. Most hard cases, from surveillance to protest, involve two rights pulling against each other, and whoever explains the balance best usually wins." },
    { type: "recap", items: ["Rights create duties in others", "Magna Carta, Locke, the great declarations", "UDHR adopted 10 December 1948", "Universality and priorities still debated"], text: "So, rights are claims that create duties. The idea grew from Magna Carta through Locke and the great declarations to the Universal Declaration in 1948, and people still argue over whose rights come first." },
    { type: "debate", motion: "Should human rights ever be limited for the sake of national security?", text: "Your turn. Should human rights ever be limited for the sake of national security? Pick the two rights in tension, and argue it on Majlis." }
  ] },
  18: { minutes: 2, beats: [
    { type: "title", heading: "Who Are 'We'?", text: "Day eighteen. You will never meet most of your fellow citizens, yet you might cry when your national team scores. Why?" },
    { type: "example", icon: "star", headline: "World Cup final", sub: "Millions of strangers united by a flag, an anthem and a team.", text: "Watch a World Cup final. Millions of people who have never met feel united by a flag, an anthem and eleven players. That powerful bond is what we call a nation." },
    { type: "versus", left: { name: "State", line: "Government, borders, laws, an army." }, right: { name: "Nation", line: "People who feel they belong together." }, text: "A nation is not the same as a state. A state is a political organisation with government, borders, laws and an army; a nation is a group who feel they belong together." },
    { type: "idea", icon: "globe", headline: "The nation-state", sub: "Each nation governing itself, powerful from the nineteenth century.", text: "The idea that each nation should govern itself became powerful in nineteenth-century Europe. As empires collapsed in the twentieth century, it spread across the world." },
    { type: "thinker", name: "Ernest Renan", dates: "1823–1892", line: "A nation is a daily plebiscite.", text: "In 1882, Ernest Renan said a nation is not race, language or geography alone, but a shared past and a desire to live together: a daily plebiscite.", say: "In 1882, Ernest Re-nan said a nation is not race, language or geography alone, but a shared past and a desire to live together: a daily pleb-i-site." },
    { type: "thinker", name: "Benedict Anderson", dates: "1936–2015", line: "Nations are imagined communities.", text: "In 1983, Benedict Anderson called nations imagined communities. Not fake, but imagined, because you will never meet most members, yet you picture yourselves as connected through shared newspapers and languages." },
    { type: "versus", left: { name: "Civic nationalism", line: "Belonging through shared citizenship and values." }, right: { name: "Ethnic nationalism", line: "Belonging through descent." }, text: "Nationalism has a double face, inspiring independence and solidarity but also wars and persecution. Scholars distinguish civic nationalism, open to anyone sharing citizenship, from ethnic nationalism, based on descent." },
    { type: "list", headline: "Identities across borders", items: ["The ummah, worldwide community of believers", "Pan-Arab movements", "Several identities at once"], text: "Other identities cross borders. For many Muslims, the ummah, the worldwide community of believers, is a profound bond, and many young people hold several identities at once.", say: "Other identities cross borders. For many Muslims, the oom-ma, the worldwide community of believers, is a profound bond, and many young people hold several identities at once." },
    { type: "scale", left: "Fellow citizens", right: "All humanity", headline: "Who do we owe more?", tilt: 0, text: "So do we owe more to fellow citizens than to strangers? Cosmopolitans, back to the Stoics, say we are first citizens of the world. Others say special loyalties are natural and good." },
    { type: "recap", items: ["A state is an institution", "A nation is a shared identity", "Renan: daily plebiscite; Anderson: imagined community", "Civic versus ethnic belonging"], text: "Recap. A state is an institution, a nation is a shared identity. Renan saw a daily vote, Anderson an imagined community, and the big question is always who gets to belong.", say: "Recap. A state is an institution, a nation is a shared identity. Re-nan saw a daily vote, Anderson an imagined community, and the big question is always who gets to belong." },
    { type: "debate", motion: "Do we owe more to our fellow citizens than to people in other countries?", text: "So, do we owe more to our fellow citizens than to people in other countries? Argue it on Majlis." }
  ] },
  19: { minutes: 2, beats: [
    { type: "title", heading: "Why Nations Rise, Fall and Fight", text: "Day nineteen. There is no world government and no global police. So why isn't the world in constant chaos?" },
    { type: "idea", icon: "globe", headline: "Anarchy, but not chaos", sub: "No ruler above states. International relations asks how they behave.", text: "Inside a country, a government enforces laws. Between countries, nobody has that power, and International Relations asks how states behave, and whether peace is possible." },
    { type: "quote", quote: "The strong do what they can and the weak suffer what they must.", by: "Athenian envoys, in Thucydides' Melian Dialogue", text: "Realism is the oldest answer. In Thucydides' Melian Dialogue, Athens tells the island of Melos to surrender, because the strong do what they can and the weak suffer what they must. Melos refuses, and Athens destroys it.", say: "Realism is the oldest answer. In Thoo-sid-i-deez' Mee-lee-an Dialogue, Athens tells the island of Mee-loss to surrender, because the strong do what they can and the weak suffer what they must. Mee-loss refuses, and Athens destroys it." },
    { type: "idea", icon: "shield", headline: "Realism: security first", sub: "In an anarchic world, states look after their own power and security.", text: "Modern realists like Hans Morgenthau and Kenneth Waltz say the international system is anarchic, with no ruler, so states must guard their own security and morals often come second." },
    { type: "thinker", name: "Immanuel Kant", dates: "1724–1804", line: "Free republics can build a perpetual peace.", text: "Liberalism is more hopeful. Its roots include Immanuel Kant's Perpetual Peace, from 1795, imagining a federation of free republican states." },
    { type: "list", headline: "The liberal case", items: ["Trade makes war costly", "Institutions help build trust", "Democracies rarely fight each other"], text: "Liberals argue that trade makes war costly, institutions like the UN build trust, and democracies rarely fight each other. Realists reply that institutions are only as strong as great powers allow." },
    { type: "thinker", name: "Ibn Khaldun", dates: "1332–1406", line: "Solidarity builds dynasties; luxury dissolves them.", text: "Centuries earlier, Ibn Khaldun, born in Tunis, explained why powers rise and fall. In his Muqaddimah, completed in 1377, he introduced asabiyya: group solidarity.", say: "Centuries earlier, Ibn Khal-doon, born in Tunis, explained why powers rise and fall. In his Mu-qad-di-ma, completed in 1377, he introduced a-sa-bee-ya: group solidarity." },
    { type: "idea", icon: "clock", headline: "The three-generation cycle", sub: "Tough groups conquer, grow comfortable, weaken, and get replaced.", text: "Tough rural groups with strong asabiyya conquer cities, then comfort weakens their solidarity until a new group replaces them. A dynasty, he suggested, lasts around three generations.", say: "Tough rural groups with strong a-sa-bee-ya conquer cities, then comfort weakens their solidarity until a new group replaces them. A dynasty, he suggested, lasts around three generations." },
    { type: "example", icon: "star", headline: "The comfy champions", sub: "The team that wins the league, then stops training hard.", text: "Think of a team that wins the league, gets comfortable, and loses to a hungrier squad. Ibn Khaldun would nod.", say: "Think of a team that wins the league, gets comfortable, and loses to a hungrier squad. Ibn Khal-doon would nod." },
    { type: "idea", icon: "brain", headline: "Constructivism", sub: "Ideas and identities, like who counts as a rival, shape behaviour.", text: "Constructivism, a newer approach, says ideas and identities shape states as much as raw power, so rivalries are partly beliefs that can change." },
    { type: "versus", left: { name: "Realist", line: "What serves national security?" }, right: { name: "Liberal", line: "What builds lasting cooperation?" }, text: "In foreign policy debates, test both lenses: a realist asks what serves security, a liberal what builds lasting cooperation. The strongest arguments work under both." },
    { type: "recap", items: ["Realism: power and security first", "Liberalism: trade, institutions, democracy", "Ibn Khaldun: solidarity rises and fades", "Constructivism: ideas shape rivalries"], text: "Recap. Realists see power, liberals see cooperation, Ibn Khaldun saw solidarity rising and fading, and constructivists see ideas shaping it all.", say: "Recap. Realists see power, liberals see cooperation, Ibn Khal-doon saw solidarity rising and fading, and constructivists see ideas shaping it all." },
    { type: "debate", motion: "Should countries put human rights ahead of trade when choosing their allies?", text: "So, should countries put human rights ahead of trade when choosing allies? Make your case on Majlis." }
  ] },
  20: { minutes: 2, beats: [
    { type: "title", heading: "Words as Weapons", text: "Day twenty. The most powerful way to control people isn't banning what they say. It's shaping what they can think." },
    { type: "idea", icon: "crown", headline: "Whoever controls words holds power", sub: "Laws, speeches, slogans and posts shape what people believe.", text: "Every political system runs on words. Speeches, slogans and posts shape what people believe, so whoever controls language holds enormous power." },
    { type: "thinker", name: "George Orwell", dates: "1903–1950", line: "Shrink the words, and you shrink thought.", text: "George Orwell feared this. In Nineteen Eighty-Four, the Party invents Newspeak, shrinking vocabulary until rebellious thoughts can't be expressed." },
    { type: "quote", quote: "War is peace.", by: "Party slogan, Nineteen Eighty-Four", text: "The Party also trains people in doublethink: accepting two contradictory beliefs at once. Slogans like war is peace flip words upside down." },
    { type: "example", icon: "flame", headline: "Pacification", sub: "Give bombing a polite name, and nobody pictures burning homes.", text: "In his essay Politics and the English Language, Orwell showed how vague words hide ugly realities. Call bombing villages pacification, and readers stop picturing burning homes." },
    { type: "list", headline: "Orwell's style rules", items: ["Prefer short, concrete words", "Cut unnecessary words", "No long word where short works"], text: "His advice: prefer short, concrete words, cut unnecessary ones, and never use a long word where a short one will do. Clear writing makes lies harder to hide." },
    { type: "example", icon: "phone", headline: "Outrage gets the clicks", sub: "Misleading clips outrun corrections; fake accounts fake popularity.", text: "Propaganda isn't only for dictators. In the 1920s, Edward Bernays wrote openly about shaping mass opinion, and today algorithms reward outrage and fake accounts make fringe views look popular." },
    { type: "thinker", name: "John Stuart Mill", dates: "1806–1873", line: "Silence an opinion, and everyone loses something.", text: "Should governments ban false speech? John Stuart Mill argued that if a silenced opinion is true, we lose the truth, and if it's partly true, we lose that part." },
    { type: "idea", icon: "book", headline: "Truth becomes dead dogma", sub: "Unchallenged truths are held without understanding why.", text: "Even a false opinion helps. Without challenge, true beliefs become dead dogma; to know your own view, you must know the best case against it." },
    { type: "versus", left: { name: "Free speech side", line: "Who decides what counts as false?" }, right: { name: "Limits side", line: "Incitement, threats and hate do real harm." }, text: "Others argue for limits. Almost every legal system restricts incitement, threats and defamation, many ban hate speech, and the United States protects far more under its First Amendment." },
    { type: "scale", left: "Free expression", right: "Preventing harm", headline: "Where's the line?", tilt: 0, text: "Many communities also see insulting the sacred as deeply harmful. The real fight is where to draw the line, and who draws it, without giving governments a tool against critics." },
    { type: "recap", items: ["Control language, control thought", "Vague words hide ugly realities", "Mill: silencing risks losing truth", "The debate is where lines go"], text: "Recap. Control language and you control thought. Vague words hide ugly truths, Mill says silencing anyone costs us, and the debate is where the lines go." },
    { type: "debate", motion: "Should governments be allowed to ban misinformation online?", text: "Should governments be allowed to ban misinformation online? Speak concretely, like Orwell would want, and argue it on Majlis." }
  ] },
  21: { minutes: 2, beats: [
    { type: "title", heading: "Studying Religion Fairly", text: "Day twenty-one, and the final part of our course: ten days on religion. Whether you're deeply religious or not at all, we start with ground rules." },
    { type: "list", headline: "Three ways to study religion", items: ["Theology: reasoning within a faith", "Religious studies: describing from outside", "Philosophy of religion: testing arguments"], text: "Three activities matter here. Theology reasons about God within a tradition, religious studies describes religions from outside, and philosophy of religion tests arguments anyone can follow." },
    { type: "thinker", name: "Anselm of Canterbury", dates: "1033–1109", line: "Theology is faith seeking understanding.", text: "Anselm called theology faith seeking understanding. In Islam, kalam built rational arguments about God's nature, and Jewish thinkers did the same.", say: "Anselm called theology faith seeking understanding. In Islam, ka-laam built rational arguments about God's nature, and Jewish thinkers did the same." },
    { type: "versus", left: { name: "Insider", line: "I know how prayer and fasting feel." }, right: { name: "Outsider", line: "I notice patterns you take for granted." }, text: "An insider knows what it feels like to fast in Ramadan, keep Shabbat or receive communion. An outsider may spot patterns insiders take for granted, and both have blind spots.", say: "An insider knows what it feels like to fast in Ramadan, keep Sha-baht or receive communion. An outsider may spot patterns insiders take for granted, and both have blind spots." },
    { type: "idea", icon: "people", headline: "Religion has many dimensions", sub: "Ritual, story, experience, ethics, institutions, buildings, art and food.", text: "Ninian Smart noted religions have many dimensions: rituals, stories, experiences, ethics, institutions, art and food. Study only doctrines, and you miss most of it." },
    { type: "example", icon: "heart", headline: "Eid, or the church choir", sub: "A teenager's faith may live in family celebrations more than textbooks.", text: "A teenager's faith might live more in Eid with family, or singing in a church choir, than in any theology book." },
    { type: "thinker", name: "al-Biruni", dates: "973–c. 1050", line: "Present their views as they state them.", text: "Around 1030, the Persian scholar al-Biruni, a devout Muslim and brilliant scientist, wrote a detailed book about India, even learning Sanskrit to read Hindu texts himself.", say: "Around 1030, the Persian scholar al Bee-roo-nee, a devout Muslim and brilliant scientist, wrote a detailed book about India, even learning Sanskrit to read Hindu texts himself." },
    { type: "idea", icon: "eye", headline: "Understand before judging", sub: "He rejected rumours and presented Hindu views in Hindus' own terms.", text: "He criticised writers who spread rumours about other peoples, and presented Hindu views as Hindus state them. He understood before judging." },
    { type: "list", headline: "Ground rules for this track", items: ["Use descriptive language", "Compare like with like", "Remember diversity within faiths", "Separate belief from truth"], text: "So, our rules. Say Muslims believe, Christians hold, Buddhists teach. Compare like with like, remember inner diversity, and keep what people believe separate from whether it's true." },
    { type: "example", icon: "mirror", headline: "The nod test", sub: "Describe a faith so fairly its followers would nod along.", text: "Here's a test. Could you describe a faith you don't share so fairly that its followers would nod and say, yes, that's us?" },
    { type: "idea", icon: "mask", headline: "Beware the straw man", sub: "Never attack a version of a faith its followers wouldn't recognise.", text: "The biggest mistake in religion debates is attacking a version of a faith its followers wouldn't recognise: the straw man. State their view fairly first." },
    { type: "recap", items: ["Theology, religious studies, philosophy differ", "Insiders and outsiders both see things", "Religion is more than doctrine", "Al-Biruni: understand before judging"], text: "Recap. Know which activity you're doing, value insiders and outsiders, remember religion is more than doctrine, and follow al-Biruni: understand before you judge.", say: "Recap. Know which activity you're doing, value insiders and outsiders, remember religion is more than doctrine, and follow al Bee-roo-nee: understand before you judge." },
    { type: "debate", motion: "Should religious education in schools teach about all major worldviews, including non-religious ones?", text: "Should religious education in schools teach about all major worldviews, including non-religious ones? Pass the nod test, then make your case on Majlis." }
  ] },
  22: { minutes: 3, beats: [
    { type: "title", heading: "Why Is There Something?", text: "Day twenty-two. Everything you have ever seen had a cause. So what caused the universe itself?" },
    { type: "example", icon: "phone", headline: "Follow the chain", sub: "Your phone came from a factory. And the factory came from...?", text: "Your phone came from a factory, a tree from a seed, you from your parents. Follow the chain back, and you hit a huge question." },
    { type: "question", big: "Why does anything exist at all?", text: "Why does anything exist at all? The cosmological argument, from the Greek kosmos, meaning world, points to God as the first cause." },
    { type: "thinker", name: "al-Kindi", dates: "c. 801–873", line: "The universe cannot be infinitely old.", text: "One famous version comes from al-Kindi, the ninth-century philosopher of the Arabs, who argued the universe cannot be infinitely old, so it had a beginning, and therefore a cause.", say: "One famous version comes from al Kin-dee, the ninth-century philosopher of the Arabs, who argued the universe cannot be infinitely old, so it had a beginning, and therefore a cause." },
    { type: "idea", icon: "book", headline: "The kalam tradition", sub: "Developed by Muslim theologians and al-Ghazali; revived by William Lane Craig.", text: "The theologians of kalam and later al-Ghazali developed this, and William Lane Craig revived it as the kalam cosmological argument.", say: "The theologians of ka-laam and later al Gha-zaa-lee developed this, and William Lane Craig revived it as the ka-laam cosmological argument." },
    { type: "list", headline: "The kalam argument", items: ["Whatever begins to exist has a cause", "The universe began to exist", "So the universe has a cause"], text: "Here it is in three steps. Whatever begins to exist has a cause; the universe began to exist; therefore, the universe has a cause." },
    { type: "thinker", name: "Ibn Sina", dates: "980–1037", line: "There must be a Necessary Existent.", text: "Ibn Sina argued from contingency. Contingent things depend on something else, and if everything were contingent, nothing would explain why anything exists.", say: "Ibn See-na argued from contingency. Contingent things depend on something else, and if everything were contingent, nothing would explain why anything exists." },
    { type: "idea", icon: "bulb", headline: "The Necessary Existent", sub: "Something that exists by its own nature, which Ibn Sina identified with God.", text: "So, he argued, there must be a Necessary Existent: something that exists by its own nature, depending on nothing else. Ibn Sina identified it with God.", say: "So, he argued, there must be a Necessary Existent: something that exists by its own nature, depending on nothing else. Ibn See-na identified it with God." },
    { type: "thinker", name: "Thomas Aquinas", dates: "1225–1274", line: "There must be a first, unmoved mover.", text: "In the thirteenth century, Thomas Aquinas set out Five Ways to show God exists. Three are cosmological: from change, from causes, and from contingency." },
    { type: "idea", icon: "scroll", headline: "Reason and revelation", sub: "Aquinas drew on Aristotle, Ibn Sina and Maimonides.", text: "Aquinas drew on Aristotle, Ibn Sina and Maimonides. Interestingly, he thought reason alone couldn't prove the universe had a beginning; he accepted that from revelation.", say: "Aquinas drew on Aristotle, Ibn See-na and My-mon-i-deez. Interestingly, he thought reason alone couldn't prove the universe had a beginning; he accepted that from revelation." },
    { type: "thinker", name: "David Hume", dates: "1711–1776", line: "Why does the chain need a first link?", text: "Now the critics. David Hume asked why the chain of causes needs a first member at all. If each link is explained by the one before it, what is left to explain?" },
    { type: "versus", left: { name: "Critic", line: "Then what caused God?" }, right: { name: "Defender", line: "Only things that begin need causes." }, text: "Others ask, if everything needs a cause, what caused God? Defenders reply that the argument only says things that begin to exist, or contingent things, need a cause, and God is defined as neither." },
    { type: "scale", left: "A real beginning", right: "Physics may explain it", headline: "Does the Big Bang help?", tilt: 0, text: "Modern physics adds fuel. The Big Bang theory suggests the observable universe had a hot, dense beginning about 13.8 billion years ago, which some see as support. Others say physics may one day explain the Big Bang itself." },
    { type: "idea", icon: "brain", headline: "Target a premise", sub: "Challenge one premise precisely, or show why God needs no cause.", text: "In debate, this argument's premises sound like common sense. To challenge it, target one premise precisely; to defend it, explain why God isn't just another thing needing a cause." },
    { type: "recap", items: ["From the universe to a first cause", "Kalam: the universe began", "Contingency: a necessary being", "Critics: why a first cause, why God?"], text: "Recap. The cosmological argument reasons from the universe to a first cause or necessary being. Al-Kindi and kalam focus on a beginning, Ibn Sina and Aquinas on contingency, and critics ask why a first cause, and why God.", say: "Recap. The cosmological argument reasons from the universe to a first cause or necessary being. Al Kin-dee and ka-laam focus on a beginning, Ibn See-na and Aquinas on contingency, and critics ask why a first cause, and why God." },
    { type: "debate", motion: "Does the existence of the universe need an explanation outside itself?", text: "So, does the existence of the universe need an explanation outside itself? Pick a premise, and argue it on Majlis." }
  ] },
  23: { minutes: 2, beats: [
    { type: "title", heading: "A Watch on the Heath", text: "Day twenty-three. Find a watch in a field and you'd assume someone made it. So what should you conclude about an eye?" },
    { type: "example", icon: "clock", headline: "Stone versus watch", sub: "Nobody asks who made a stone. Everyone asks who made a watch.", text: "Kick a stone and you won't wonder who made it. But find a watch, gears and springs fitting perfectly, and you'd be sure it was designed." },
    { type: "thinker", name: "William Paley", dates: "1743–1805", line: "A watch implies a watchmaker.", text: "In 1802, the clergyman William Paley argued that living things like the eye are far more intricate than any watch, so they too must have a designer: God." },
    { type: "idea", icon: "eye", headline: "The design argument", sub: "From the Greek telos, purpose: order in nature points to a mind.", text: "This is the design, or teleological, argument, from the Greek telos, purpose. The Quran points to night, day and plants as signs for those who reflect, and the Psalms say the heavens declare the glory of God.", say: "This is the design, or tee-lee-o-lodge-i-cal, argument, from the Greek tel-oss, purpose. The Quran points to night, day and plants as signs for those who reflect, and the Psalms say the heavens declare the glory of God." },
    { type: "thinker", name: "David Hume", dates: "1711–1776", line: "We've seen watches made, never universes.", text: "The sharpest early critic was David Hume. We have seen watches made, but never universes, so the analogy is weak. And why one designer rather than a committee?" },
    { type: "timeline", events: [{ year: "1779", label: "Hume's Dialogues published" }, { year: "1802", label: "Paley's Natural Theology" }, { year: "1859", label: "Darwin: Origin of Species" }], text: "In 1859, Charles Darwin's On the Origin of Species showed how complex features like eyes could develop gradually through natural selection, as small helpful variations were passed on." },
    { type: "versus", left: { name: "Many sceptics", line: "Evolution removes the need for a designer." }, right: { name: "Many religious scientists", line: "Evolution may be how God works." }, text: "For many, this removed the need for a designer in biology. Others, including many religious scientists, argued that evolution could itself be the way God works." },
    { type: "idea", icon: "star", headline: "Fine-tuning", sub: "Physical constants sit in narrow ranges that allow stars and life.", text: "Recently the argument has returned as fine-tuning. Constants like gravity's strength fall within narrow ranges that allow stars and life; slightly different, many argue, and life would be impossible." },
    { type: "example", icon: "phone", headline: "Every slider set just right", sub: "Like a game where every setting must be perfect, or nothing works.", text: "Imagine dozens of sliders that all must be set just right, or nothing works. Supporters say a designer explains that better than chance." },
    { type: "scale", left: "A designer", right: "Many universes", headline: "Designer or multiverse?", tilt: 0, text: "Critics suggest a multiverse: countless universes with different constants, and we naturally find ourselves in one that permits life. Theists reply that this is unproven and just moves the question back." },
    { type: "recap", items: ["Paley: complexity implies a designer", "Hume: the analogy is weak", "Darwin: natural selection explains biology", "Fine-tuning versus the multiverse"], text: "Recap. Paley saw a designer behind complexity, Hume attacked the analogy, Darwin offered natural selection, and today fine-tuning faces off against the multiverse." },
    { type: "debate", motion: "Does the fine-tuning of the universe point to a designer?", text: "Does fine-tuning point to a designer? Bring an explanation, not scorn, and argue it on Majlis." }
  ] },
  24: { minutes: 3, beats: [
    { type: "title", heading: "If God Is Good, Why Suffering?", text: "Day twenty-four. This is the hardest question believers face, and it deserves serious, compassionate treatment from all sides." },
    { type: "example", icon: "heart", headline: "Real lives, real pain", sub: "An earthquake. A sick child. A good person betrayed.", text: "An earthquake kills thousands. A child develops a painful illness. A good person is betrayed." },
    { type: "question", big: "If God is good and all-powerful, why suffering?", text: "Believers and non-believers alike feel this. If God is all-powerful, all-knowing and perfectly good, why does suffering exist? This is the problem of evil." },
    { type: "thinker", name: "Epicurus", dates: "341–270 BC", line: "Willing but unable? Able but unwilling?", text: "A version is traditionally attributed to the Greek philosopher Epicurus. Is God willing to prevent evil but not able? Then he is not all-powerful." },
    { type: "idea", icon: "question", headline: "The other horns", sub: "Able but not willing? Then not good. Both? Then why evil?", text: "Able but not willing? Then he is not good. And if both, why does evil exist at all?" },
    { type: "versus", left: { name: "Logical problem", line: "God and evil flatly contradict." }, right: { name: "Evidential problem", line: "So much pointless suffering makes God unlikely." }, text: "Philosophers split this in two. The logical problem says God and evil contradict; the evidential problem says the sheer amount of seemingly pointless suffering, like a fawn dying unseen in a forest fire, makes God unlikely." },
    { type: "thinker", name: "Augustine of Hippo", dates: "354–430", line: "Evil is a lack of good.", text: "Augustine argued God created everything good. Evil is not a thing but a privation, a lack of goodness, like a hole in a sock, and it entered through misused free will." },
    { type: "example", icon: "phone", headline: "Love, or robots?", sub: "A friend programmed to like you isn't really a friend.", text: "Why allow free will? A friend programmed to like you isn't really a friend, and Augustine held that free creatures who can choose love beat a world of robots." },
    { type: "thinker", name: "John Hick", dates: "1922–2012", line: "This world is a place of soul-making.", text: "Inspired by Irenaeus, John Hick developed the soul-making view: humans are created immature, and a world of challenge and risk is where courage, compassion and patience grow.", say: "Inspired by Eye-ren-ay-us, John Hick developed the soul-making view: humans are created immature, and a world of challenge and risk is where courage, compassion and patience grow." },
    { type: "idea", icon: "scroll", headline: "The Book of Job", sub: "No neat answers: God speaks from a whirlwind about creation's vastness.", text: "The Book of Job refuses neat answers. Job's suffering is not his fault, his friends' explanations are rejected, and God answers from a whirlwind, pointing to creation's vastness.", say: "The Book of Jobe refuses neat answers. Jobe's suffering is not his fault, his friends' explanations are rejected, and God answers from a whirlwind, pointing to creation's vastness." },
    { type: "idea", icon: "mosque", headline: "Life as a test", sub: "The Quran describes death and life as created to test our deeds.", text: "Islamic thought offers related themes. The Quran describes this life as a test: in Surah al-Mulk, God is described as having created death and life to test which of you is best in deed.", say: "Islamic thought offers related themes. The Quran describes this life as a test: in Soo-ra al Mulk, God is described as having created death and life to test which of you is best in deed." },
    { type: "list", headline: "Muslim responses", items: ["Hikma: God's wisdom exceeds ours", "Sabr: patience in hardship rewarded", "This world is not final"], text: "Many Muslim thinkers stress that God's wisdom, hikma, goes beyond human understanding, that patience, sabr, in hardship is rewarded, and that this world is not the final stage.", say: "Many Muslim thinkers stress that God's wisdom, hik-ma, goes beyond human understanding, that patience, sab-er, in hardship is rewarded, and that this world is not the final stage." },
    { type: "versus", left: { name: "Atheist critics", line: "Free will doesn't explain earthquakes or animal pain." }, right: { name: "Sceptical theists", line: "We shouldn't expect to see God's reasons." }, text: "Atheist philosophers respond that free will doesn't explain natural disasters or animal suffering, and soul-making doesn't explain suffering that crushes people. Appeals to mystery, they argue, could defend anything." },
    { type: "idea", icon: "dove", headline: "Debate with care", sub: "Real grief is involved. Never mock either side's pain.", text: "This topic demands care, because real grief is involved. Present both sides at full strength, say whether you mean the logical or evidential problem, and never mock anyone's pain." },
    { type: "recap", items: ["How can God and suffering coexist?", "Logical versus evidential problem", "Free will, soul-making, life as test", "Critics: natural and animal suffering"], text: "Recap. The problem of evil asks how a good, all-powerful God fits with suffering. Responses include free will, soul-making and life as a test, and critics answer with natural disasters and animal suffering." },
    { type: "debate", motion: "Is the existence of suffering a good reason to doubt the existence of God?", text: "Is the existence of suffering a good reason to doubt the existence of God? Take it seriously, argue it kindly, on Majlis." }
  ] },
  25: { minutes: 2, beats: [
    { type: "title", heading: "Faith and Reason: Ghazali vs Ibn Rushd", text: "Day twenty-five. In the twelfth century, two Muslim thinkers wrote books with almost the same title, arguing in opposite directions." },
    { type: "versus", left: { name: "al-Ghazali", line: "Philosophers claim proofs reason can't deliver." }, right: { name: "Ibn Rushd", line: "Truth cannot contradict truth." }, text: "Al-Ghazali wrote The Incoherence of the Philosophers, and about a century later Ibn Rushd replied with The Incoherence of the Incoherence. Best comeback title in history.", say: "Al Gha-zaa-lee wrote The Incoherence of the Philosophers, and about a century later Ibn Rushd replied with The Incoherence of the Incoherence. Best comeback title in history." },
    { type: "thinker", name: "al-Ghazali", dates: "1058–1111", line: "Logic is valuable, but philosophers overstepped.", text: "Al-Ghazali valued logic, but argued philosophers like Ibn Sina claimed to prove things reason cannot establish, such as that the world is eternal.", say: "Al Gha-zaa-lee valued logic, but argued philosophers like Ibn See-na claimed to prove things reason cannot establish, such as that the world is eternal." },
    { type: "example", icon: "bulb", headline: "Flip the switch", sub: "You see one thing follow another, never the necessary connection.", text: "He also argued we never observe a necessary link between cause and effect. Flip a switch and the light comes on, but you only see one thing follow another, and God could act otherwise." },
    { type: "thinker", name: "Ibn Rushd", dates: "1126–1198", line: "The Quran commands us to reflect on creation.", text: "Ibn Rushd, known in Europe as Averroes, was a judge in Córdoba. He argued the Quran commands reflection on creation, so philosophy is permitted, even obligatory, for the capable.", say: "Ibn Rushd, known in Europe as Av-err-oh-eez, was a judge in Kor-do-ba. He argued the Quran commands reflection on creation, so philosophy is permitted, even obligatory, for the capable." },
    { type: "idea", icon: "scroll", headline: "Truth cannot contradict truth", sub: "If proof seems to clash with scripture, interpret the text to harmonise them.", text: "His key principle: truth cannot contradict truth. If a demonstration seems to clash with scripture, interpret the text so they harmonise." },
    { type: "list", headline: "Others on the same problem", items: ["Maimonides: read many descriptions figuratively", "Aquinas: two routes, one truth"], text: "Maimonides' Guide for the Perplexed read many biblical descriptions of God figuratively, and Aquinas held that faith and reason are two routes to one truth.", say: "My-mon-i-deez' Guide for the Perplexed read many biblical descriptions of God figuratively, and Aquinas held that faith and reason are two routes to one truth." },
    { type: "thinker", name: "Blaise Pascal", dates: "1623–1662", line: "Belief in God is the wise bet.", text: "Blaise Pascal offered a wager. If reason can't settle whether God exists, you must still choose: believe and be right, you gain infinitely; be wrong, you lose little." },
    { type: "scale", left: "Believe", right: "Don't believe", headline: "Pascal's wager", tilt: 0, text: "Critics ask which God to bet on, and whether believing for a reward is genuine faith. Pascal also wrote that the heart has its reasons which reason does not know." },
    { type: "versus", left: { name: "W. K. Clifford", line: "Never believe on insufficient evidence." }, right: { name: "William James", line: "Some choices can't wait for proof." }, text: "In 1877, W. K. Clifford argued it is wrong always, everywhere, and for anyone, to believe anything upon insufficient evidence. William James replied that some choices, like trusting a friend, can't wait for proof." },
    { type: "recap", items: ["Al-Ghazali: reason has limits", "Ibn Rushd: truth cannot contradict truth", "Pascal: belief as a wager", "Clifford and James on evidence"], text: "Recap. Al-Ghazali marked reason's limits, Ibn Rushd defended philosophy, Pascal made belief a bet, and Clifford and James argued over evidence. Skip the lazy faith-versus-science contrast.", say: "Recap. Al Gha-zaa-lee marked reason's limits, Ibn Rushd defended philosophy, Pascal made belief a bet, and Clifford and James argued over evidence. Skip the lazy faith-versus-science contrast." },
    { type: "debate", motion: "Can it be rational to believe something without sufficient evidence?", text: "Can it be rational to believe something without sufficient evidence? Ask what counts as good evidence, then argue it on Majlis." }
  ] },
  26: { minutes: 2, beats: [
    { type: "title", heading: "Reading Sacred Texts", text: "Day twenty-six. The same verse can be read many ways, and every major tradition has rules for deciding how." },
    { type: "example", icon: "phone", headline: "Screenshot without context", sub: "A message cropped from its chat can seem to mean the opposite.", text: "Ever had a message screenshotted out of context and misread? Texts don't interpret themselves, and hermeneutics asks how we should read them.", say: "Ever had a message screenshotted out of context and misread? Texts don't interpret themselves, and her-muh-new-tics asks how we should read them." },
    { type: "idea", icon: "mosque", headline: "Tafsir", sub: "Interpreting the Quran through Arabic, context, other verses and the Sunnah.", text: "Muslims believe the Quran is God's word, revealed to the Prophet Muhammad over about twenty-three years in Arabic. Interpreting it is called tafsir.", say: "Muslims believe the Quran is God's word, revealed to the Prophet Muhammad over about twenty-three years in Arabic. Interpreting it is called taf-seer." },
    { type: "thinker", name: "al-Tabari", dates: "839–923", line: "Gather what earlier generations explained.", text: "Classical scholars like al-Tabari compiled explanations from the Prophet, his companions and their successors. Interpreters study Arabic grammar, the circumstances of revelation, and how verses relate to each other.", say: "Classical scholars like al Ta-ba-ree compiled explanations from the Prophet, his companions and their successors. Interpreters study Arabic grammar, the circumstances of revelation, and how verses relate to each other." },
    { type: "idea", icon: "book", headline: "Clear and ambiguous verses", sub: "The Quran (3:7) speaks of muhkam and mutashabih verses.", text: "The Quran, in Surah Al Imran, calls some verses clear and decisive, muhkam, and others ambiguous or allegorical, mutashabih. Handling the latter has been discussed for centuries.", say: "The Quran, in Surah Aal Im-raan, calls some verses clear and decisive, muh-kam, and others ambiguous or allegorical, mu-ta-shaa-bih. Handling the latter has been discussed for centuries." },
    { type: "idea", icon: "synagogue", headline: "Written and Oral Torah", sub: "Recorded in the Mishnah around 200 CE, expanded in the Talmud.", text: "In Judaism, rabbinic tradition holds that Moses received a written and an oral Torah at Sinai. The oral teaching was recorded in the Mishnah around 200 CE, then expanded in the Talmud.", say: "In Judaism, rabbinic tradition holds that Moses received a written and an oral Torah at Sinai. The oral teaching was recorded in the Mish-na around 200 CE, then expanded in the Tal-mood." },
    { type: "thinker", name: "Rashi", dates: "1040–1105", line: "Explain the text, line by line.", text: "The Talmud keeps minority opinions alongside majority ones, and commentators like Rashi, in eleventh-century France, wrote line-by-line explanations still studied today.", say: "The Tal-mood keeps minority opinions alongside majority ones, and commentators like Rah-shee, in eleventh-century France, wrote line-by-line explanations still studied today." },
    { type: "list", headline: "Christian approaches", items: ["Literal and spiritual senses", "Reformation: scripture alone", "Catholic: scripture within tradition"], text: "Augustine recognised literal and spiritual senses of the Bible. In the Reformation, Luther stressed scripture alone, while the Catholic Church emphasised scripture within its tradition." },
    { type: "thinker", name: "Baruch Spinoza", dates: "1632–1677", line: "Study scripture like nature: language and history.", text: "From the seventeenth century, Spinoza argued scripture should be studied like nature, through language and history. Many believers use such methods; others see them as undermining faith." },
    { type: "scale", left: "More literal", right: "More contextual", headline: "How to read?", tilt: 0, text: "Every tradition faces the same questions: how much weight original context carries, who may interpret, and how to answer brand-new questions." },
    { type: "idea", icon: "eye", headline: "No verse-sniping", sub: "Never quote one verse out of context to attack or defend.", text: "In debate, never quote a single verse out of context, to support or attack a religion. Ask how that tradition's own scholars read it." },
    { type: "recap", items: ["Hermeneutics: the study of interpretation", "Tafsir interprets the Quran", "Torah: written plus oral", "Christian readings: spiritual to historical"], text: "Recap. Hermeneutics studies interpretation. Muslims use tafsir, Jews read the written Torah with the oral tradition, and Christians range from spiritual readings to historical criticism.", say: "Recap. Hermeneutics studies interpretation. Muslims use taf-seer, Jews read the written Torah with the oral tradition, and Christians range from spiritual readings to historical criticism." },
    { type: "debate", motion: "Should sacred texts be read mainly in light of their original historical context?", text: "Should sacred texts be read mainly in light of their original historical context? Show how each tradition reads, then argue it on Majlis." }
  ] },
  27: { minutes: 3, beats: [
    { type: "title", heading: "Good Because God Commands It?", text: "Day twenty-seven. Socrates asked a question about the gods some 2,400 years ago, and theologians in every tradition are still answering it." },
    { type: "idea", icon: "scroll", headline: "Plato's Euthyphro", sub: "A young man is off to prosecute his own father.", text: "In Plato's Euthyphro, Socrates meets a young man about to prosecute his own father. Euthyphro is sure this is pious, so Socrates starts asking questions.", say: "In Plato's You-thi-fro, Socrates meets a young man about to prosecute his own father. You-thi-fro is sure this is pious, so Socrates starts asking questions." },
    { type: "question", big: "Pious because loved, or loved because pious?", text: "Is something pious because the gods love it, or do the gods love it because it is pious?" },
    { type: "versus", left: { name: "Option one", line: "Good because God commands it." }, right: { name: "Option two", line: "God commands it because it's good." }, text: "Translate that into one-God terms, and you get the Euthyphro dilemma. Is something good because God commands it, or does God command it because it is good?", say: "Translate that into one-God terms, and you get the You-thi-fro dilemma. Is something good because God commands it, or does God command it because it is good?" },
    { type: "idea", icon: "question", headline: "Problem one: arbitrary?", sub: "If command makes it good, commanded cruelty would be good.", text: "Both answers raise problems. If something is good simply because God commands it, morality looks arbitrary: had God commanded cruelty, cruelty would be good." },
    { type: "idea", icon: "crown", headline: "Problem two: a higher standard?", sub: "If God commands what's already good, goodness seems independent of God.", text: "But if God commands things because they are good, goodness seems to exist independently of God. Then God looks like a messenger for a standard above him." },
    { type: "example", icon: "school", headline: "The rulebook test", sub: "Is it wrong because it's banned, or banned because it's wrong?", text: "Try it at school. Is bullying wrong because it's in the rulebook, or in the rulebook because it's wrong? Most people instantly pick the second, and that tells you something." },
    { type: "versus", left: { name: "Mu'tazila", line: "Reason can know good and evil." }, right: { name: "Ash'aris", line: "Good is defined by God's command." }, text: "Early Islamic theology debated this vividly. The Mu'tazila held that reason can know good and evil, at least in part: justice is good and oppression evil in themselves, and God, being just, commands accordingly.", say: "Early Islamic theology debated this vividly. The Moo-ta-zi-la held that reason can know good and evil, at least in part: justice is good and oppression evil in themselves, and God, being just, commands accordingly." },
    { type: "idea", icon: "mosque", headline: "The Ash'ari view", sub: "Humans cannot judge God by an outside standard.", text: "The Ash'aris argued that good and evil are defined by God's command, and reason alone cannot establish moral obligation. Many later scholars took positions in between, and Christians had similar debates.", say: "The Ash-a-rees argued that good and evil are defined by God's command, and reason alone cannot establish moral obligation. Many later scholars took positions in between, and Christians had similar debates." },
    { type: "idea", icon: "heart", headline: "Goodness in God's nature", sub: "Commands flow from God's perfectly good nature, not from whim.", text: "Many theists offer a way out. God's commands are not arbitrary, because they flow from God's nature, which is perfectly good, so goodness is neither above God nor invented on a whim." },
    { type: "question", big: "But why is God's nature the standard?", text: "Critics ask whether this just moves the question back a step. Why is God's nature the standard of good?" },
    { type: "thinker", name: "Thomas Aquinas", dates: "1225–1274", line: "Reason can discover the natural law.", text: "A second approach is natural law, which Thomas Aquinas developed from Aristotle. Humans have built-in purposes, like living, raising children, seeking truth and living in society, and reason can discover the moral rules that protect them." },
    { type: "thinker", name: "al-Shatibi", dates: "d. 1388", line: "The sharia protects life, mind and more.", text: "In Islamic law, al-Ghazali and later al-Shatibi described the higher objectives of the sharia, the maqasid: protecting religion, life, intellect, lineage and property. Scholars used these to reason about new cases.", say: "In Islamic law, al Gha-zaa-lee and later al Sha-tee-bee described the higher objectives of the sharia, the ma-qaa-sid: protecting religion, life, intellect, lineage and property. Scholars used these to reason about new cases." },
    { type: "scale", left: "Needs God", right: "Stands on its own", headline: "Morality without God?", tilt: 0, text: "So can morality be objective without God? It is one of the great open questions. Use the dilemma fairly, and give the believer's best reply before pressing your challenge." },
    { type: "recap", items: ["Good because commanded, or commanded because good?", "Mu'tazila: reason; Ash'aris: command", "Theists: goodness flows from God's nature", "Natural law and maqasid use reason"], text: "Recap. The Euthyphro dilemma pulls goodness and command apart. The Mu'tazila and Ash'aris took different sides, many theists ground goodness in God's nature, and natural law and the maqasid use reason to find purposes.", say: "Recap. The You-thi-fro dilemma pulls goodness and command apart. The Moo-ta-zi-la and Ash-a-rees took different sides, many theists ground goodness in God's nature, and natural law and the ma-qaa-sid use reason to find purposes." },
    { type: "debate", motion: "Can there be objective morality without God?", text: "Can there be objective morality without God? State the other side's best reply, then argue it on Majlis." }
  ] },
  28: { minutes: 2, beats: [
    { type: "title", heading: "Karma, the Buddha and the Dao", text: "Day twenty-eight. Over a billion people believe you have lived many lives before this one. Here's how they understand the journey." },
    { type: "list", headline: "Key Hindu ideas", items: ["Samsara: the cycle of rebirth", "Karma: actions shape future lives", "Dharma: duty and cosmic order", "Moksha: liberation from rebirth"], text: "Hinduism is a family of traditions rooted in the Vedas and Upanishads. Many Hindus believe in samsara, the cycle of rebirth, and karma: cause and effect across lifetimes.", say: "Hinduism is a family of traditions rooted in the Vay-das and Oo-pa-ni-shads. Many Hindus believe in sum-saa-ra, the cycle of rebirth, and karma: cause and effect across lifetimes." },
    { type: "idea", icon: "lotus", headline: "Dharma and moksha", sub: "Right conduct now; ultimately, liberation from the cycle of rebirth.", text: "Dharma means duty, right conduct and cosmic order, and the goal is moksha, liberation from rebirth. Some schools teach the self is one with Brahman; others stress devotion to a personal God.", say: "Dar-ma means duty, right conduct and cosmic order, and the goal is moke-sha, liberation from rebirth. Some schools teach the self is one with Brah-mun; others stress devotion to a personal God." },
    { type: "list", headline: "The Bhagavad Gita", items: ["Set on a battlefield", "Arjuna lays down his bow", "Krishna teaches duty and detachment"], text: "In the Bhagavad Gita, the warrior Arjuna lays down his bow, horrified at fighting his own relatives. The god Krishna, his charioteer, teaches him about duty and acting without attachment to results.", say: "In the Bah-ga-vad Gee-ta, the warrior Ar-ju-na lays down his bow, horrified at fighting his own relatives. The god Krishna, his charioteer, teaches him about duty and acting without attachment to results." },
    { type: "idea", icon: "lotus", headline: "The Buddha, the awakened one", sub: "Siddhartha Gautama chose a Middle Way between indulgence and harsh self-denial.", text: "Siddhartha Gautama, the Buddha, lived in northern India around the fifth century BC. Tradition says he left a prince's luxury, tried extreme self-denial, then chose a Middle Way.", say: "Sid-daar-ta Gow-ta-ma, the Buddha, lived in northern India around the fifth century BC. Tradition says he left a prince's luxury, tried extreme self-denial, then chose a Middle Way." },
    { type: "list", headline: "The Four Noble Truths", items: ["Life involves dukkha, suffering", "Suffering arises from craving", "Suffering can end: nirvana", "The Eightfold Path leads there"], text: "In his first sermon he taught the Four Noble Truths. Life involves dukkha, suffering or unsatisfactoriness; it arises from craving; it can end, in nirvana; and the Noble Eightfold Path leads there.", say: "In his first sermon he taught the Four Noble Truths. Life involves doo-ka, suffering or unsatisfactoriness; it arises from craving; it can end, in nirvana; and the Noble Eightfold Path leads there." },
    { type: "example", icon: "phone", headline: "Five minutes of satisfaction", sub: "You get the thing you wanted, then feel restless again.", text: "Ever got what you wanted, then felt restless five minutes later? Buddhists teach that craving keeps that cycle going, and most focus on practice and insight rather than a creator God." },
    { type: "thinker", name: "Laozi", dates: "", line: "Be like water: soft, yet it wears stone.", text: "In China, Daoism centres on the Dao, the Way: reality's underlying flow, which can't be fully named. Its classic, the Dao De Jing, is traditionally attributed to Laozi.", say: "In China, Dow-ism centres on the Dow, the Way: reality's underlying flow, which can't be fully named. Its classic, the Dow De Jing, is traditionally attributed to Lao-dzuh." },
    { type: "thinker", name: "Zhuangzi", dates: "", line: "Am I a man, or a dreaming butterfly?", text: "Zhuangzi dreamed he was a butterfly, then woke and wondered: was he a man who dreamed of being a butterfly, or a butterfly dreaming of being a man?", say: "Jwang-dzuh dreamed he was a butterfly, then woke and wondered: was he a man who dreamed of being a butterfly, or a butterfly dreaming of being a man?" },
    { type: "recap", items: ["Hinduism: samsara, karma, dharma, moksha", "Buddhism: Four Noble Truths, Middle Way", "Daoism: the Way and wu wei", "Understand each on its own terms"], text: "Recap. Many Hindus seek moksha, Buddhists follow the Middle Way toward nirvana, and Daoists seek harmony with the Way. Don't force them into Abrahamic boxes, and know moksha from nirvana.", say: "Recap. Many Hindus seek moke-sha, Buddhists follow the Middle Way toward nirvana, and Dow-ists seek harmony with the Way. Don't force them into Abrahamic boxes, and know moke-sha from nirvana." },
    { type: "debate", motion: "Is the idea of karma a fairer explanation of suffering than the idea of a test?", text: "Is the idea of karma a fairer explanation of suffering than the idea of a test? Compare carefully, and argue it on Majlis." }
  ] },
  29: { minutes: 2, beats: [
    { type: "title", heading: "God and Government", text: "Day twenty-nine. From Medina to Paris, people have arranged faith and power in many ways, and every model has passionate defenders." },
    { type: "example", icon: "school", headline: "Headscarf, cross or kippah?", sub: "Should a teacher be allowed to wear one at work?", text: "Should a teacher be allowed to wear a headscarf, a cross or a kippah at work? Should a state have an official religion? These questions stir strong feelings from the Gulf to France.", say: "Should a teacher be allowed to wear a headscarf, a cross or a kee-pa at work? Should a state have an official religion? These questions stir strong feelings from the Gulf to France." },
    { type: "timeline", events: [{ year: "313", label: "Edict of Milan" }, { year: "622", label: "Charter of Medina" }, { year: "1648", label: "Peace of Westphalia" }, { year: "1905", label: "French separation law" }], text: "Here's the quick tour: toleration in Rome in 313, the Charter of Medina in 622, the Peace of Westphalia in 1648, and France's separation law in 1905." },
    { type: "idea", icon: "mosque", headline: "The Charter of Medina", sub: "Rights and duties among Muslims, Arab tribes and Jewish tribes.", text: "In 622, after the Prophet Muhammad's migration to Medina, the Charter of Medina set out relations between Muslims, Arab tribes and Jewish tribes. Later, the Ottomans organised religious communities into millets." },
    { type: "thinker", name: "Constantine", dates: "c. 272–337", line: "Toleration for Christians across the empire.", text: "In Rome, Christians were sometimes persecuted until Constantine granted toleration in the Edict of Milan in 313. Later that century, Christianity became the official religion." },
    { type: "thinker", name: "John Locke", dates: "1632–1704", line: "True faith cannot be forced.", text: "After Europe's religious wars, John Locke's Letter Concerning Toleration, in 1689, argued government protects life and property, while souls are each person's own care, since true faith cannot be forced." },
    { type: "list", headline: "Models today", items: ["England: an established church", "Gulf states: Islam as state religion", "France: strict laïcité", "India: secular, recognising diversity"], text: "Today models vary widely. England has an established church yet broad religious freedom, Gulf states name Islam as the state religion, France keeps religion out of state institutions, and India calls itself secular." },
    { type: "versus", left: { name: "Religious foundation", line: "Shared faith gives moral direction and unity." }, right: { name: "Secularism", line: "Separation treats all faiths and none equally." }, text: "Supporters of a religious foundation say shared faith gives moral direction and cohesion. Secularists say separation protects religion from the state and treats citizens of all faiths and none equally." },
    { type: "scale", left: "Shared faith", right: "Equal freedom", headline: "What should the state protect?", tilt: 0, text: "In debate, don't assume your country's model is the only sensible one. Ask what each arrangement protects, faith, freedom, equality or unity, then argue the balance in a specific case." },
    { type: "recap", items: ["Medina: communities with defined rights", "Constantine, Westphalia, Locke shaped Europe", "From established churches to strict secularism", "Ask what each model protects"], text: "Recap. Medina, Rome, Westphalia and Locke all shaped how faith and power fit together, and today's models, from established churches to strict secularism, each protect different things." },
    { type: "debate", motion: "Should religious symbols be allowed in state schools and public jobs?", text: "Should religious symbols be allowed in state schools and public jobs? Ask what each side is protecting, then argue it on Majlis." }
  ] },
  30: { minutes: 3, beats: [
    { type: "title", heading: "Doubt and Good-Faith Debate", text: "Day thirty, the final lesson. A madman runs into a marketplace with a lantern in daylight, shouting that he seeks God. Hold that thought." },
    { type: "idea", icon: "people", headline: "Two goals today", sub: "Understand modern atheism and doubt, then master disagreeing well.", text: "Throughout this course, believers and sceptics have made their best cases. Today: modern atheism and doubt, then the skill that ties everything together, disagreeing well." },
    { type: "thinker", name: "Bertrand Russell", dates: "1872–1970", line: "The burden of proof is on the claimant.", text: "In 1927, Bertrand Russell gave a lecture called Why I Am Not a Christian, arguing the traditional proofs for God fail and religion is largely based on fear." },
    { type: "idea", icon: "globe", headline: "Russell's teapot", sub: "A teapot orbiting the Sun: impossible to disprove, but is belief reasonable?", text: "He later imagined a teapot orbiting the Sun, too small for any telescope to see. Nobody could disprove it, but that wouldn't make believing in it reasonable." },
    { type: "example", icon: "school", headline: "The dog ate my homework", sub: "Your teacher can't disprove it, but the burden is on you.", text: "It's like telling your teacher the dog ate your homework. They can't disprove it, but the burden of proof is on you." },
    { type: "idea", icon: "book", headline: "Believers reply", sub: "God isn't an object in the universe, but the explanation of it.", text: "Believers reply that God isn't an object inside the universe, like a teapot, but the explanation of why there is a universe at all." },
    { type: "thinker", name: "Friedrich Nietzsche", dates: "1844–1900", line: "What will replace God as our foundation?", text: "Friedrich Nietzsche wrote one of philosophy's most misunderstood lines. In The Gay Science, from 1882, a madman seeks God in the marketplace, and the unbelieving crowd laughs.", say: "Friedrich Nee-cha wrote one of philosophy's most misunderstood lines. In The Gay Science, from 1882, a madman seeks God in the marketplace, and the unbelieving crowd laughs." },
    { type: "quote", quote: "God is dead, and we have killed him.", by: "The madman, in Nietzsche's The Gay Science", text: "Then he announces: God is dead, and we have killed him. Nietzsche wasn't celebrating; he meant belief in God had stopped being the foundation of European culture.", say: "Then he announces: God is dead, and we have killed him. Nee-cha wasn't celebrating; he meant belief in God had stopped being the foundation of European culture." },
    { type: "idea", icon: "flame", headline: "The threat of nihilism", sub: "If nothing replaces God as our foundation, does anything matter?", text: "He warned that people hadn't grasped the consequences. If God was the basis of morality and meaning, what would replace him? He feared nihilism, unless humans created new values." },
    { type: "list", headline: "Responses", items: ["Religious thinkers: Nietzsche saw the stakes", "Plantinga: belief can be rational", "Humanists: wellbeing, reason, empathy"], text: "Many religious thinkers see Nietzsche's stakes as a reason for belief. Alvin Plantinga argued belief in God can be rational without proof, like belief in other minds, while secular humanists ground morality in wellbeing and empathy.", say: "Many religious thinkers see Nee-cha's stakes as a reason for belief. Alvin Plantinga argued belief in God can be rational without proof, like belief in other minds, while secular humanists ground morality in wellbeing and empathy." },
    { type: "question", big: "Arguing to win, or to find the truth?", text: "Now the art this whole course has been building towards. Good-faith debate means arguing to find the truth, not just to win." },
    { type: "versus", left: { name: "Straw man", line: "Attack the weakest version." }, right: { name: "Steelman", line: "Build the strongest version first." }, text: "Start with the principle of charity: read others' words in their most reasonable sense. Then build a steelman, the opposite of a straw man: the strongest version of your opponent's view." },
    { type: "thinker", name: "al-Shafi'i", dates: "767–820", line: "My view is correct but may be wrong.", text: "Islamic tradition has a rich literature on adab al-ikhtilaf, the etiquette of disagreement. A saying attributed to al-Shafi'i: my view is correct but may be wrong; the other's view is wrong but may be correct.", say: "Islamic tradition has a rich literature on a-dab al ikh-ti-laaf, the etiquette of disagreement. A saying attributed to ash Sha-fee-ee: my view is correct but may be wrong; the other's view is wrong but may be correct." },
    { type: "example", icon: "phone", headline: "Before you hit reply", sub: "Could you make their case so well they'd applaud?", text: "So here's your final tool. Before you argue, ask: do I understand the other side well enough to make its case? If not, keep listening." },
    { type: "recap", items: ["Russell: burden of proof on the claimant", "Nietzsche: a warning, not a celebration", "Steelman before you critique", "Disagree honestly, leave wiser"], text: "Recap. Russell put the burden of proof on the claimant, Nietzsche warned of nihilism, and good-faith debate means charity and steelmanning. That's the spirit of the majlis: sit together, disagree honestly, leave wiser.", say: "Recap. Russell put the burden of proof on the claimant, Nee-cha warned of nihilism, and good-faith debate means charity and steelmanning. That's the spirit of the majlis: sit together, disagree honestly, leave wiser." },
    { type: "debate", motion: "Is it possible to live a fully meaningful life without religion?", text: "Last debate of the course: is it possible to live a fully meaningful life without religion? Steelman the other side first, then make your case on Majlis." }
  ] }
});
